css:
.loader { display: flex; flex-direction: column; gap: calc(var(--loader-size) * .06); width: var(--loader-size); padding: calc(var(--loader-size) * .07); border-radius: calc(var(--loader-size) * .1); background: color-mix(in srgb, var(--loader-color) 10%, transparent); box-sizing: border-box; animation: twPulse calc(var(--loader-speed) * 1.6) cubic-bezier(.4, 0, .6, 1) infinite; }
.loader .thumb { height: calc(var(--loader-size) * .38); border-radius: calc(var(--loader-size) * .07); background: color-mix(in srgb, var(--loader-color) 38%, transparent); }
.loader .line { height: calc(var(--loader-size) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 26%, transparent); }
.loader .line.short { width: 60%; }
@keyframes twPulse { 50% { opacity: .45; } }
